/** Čitalac je "ti". Imena znakova, datumi i teme stižu u nominativu, a padež bira sr-cases. Kuće se čuvaju u lokativu, posle "u". */
const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
const myGen = (monthYear: string) => monthYear.replace(/^\p{L}+/u, mGen);
/** The closing sentence of a search snippet, in each sign's own words: a long one and a short one, so the snippet fits. */
const TAIL: Record<string, [string, string]> = {
  Ovan: ["Ljubav, posao, novac i najbolji dani za tvoj prvi potez.", "Ljubav, posao i dani za prvi potez."],
  Bik: ["Novac, ljubav, posao i dani kada se strpljenje zaista isplati.", "Novac, ljubav i dani koji se isplate."],
  Blizanci: ["Razgovori, ljubav, posao i dani kada te drugi najbolje čuju.", "Razgovori, ljubav i najbolji dani."],
  Rak: ["Dom, ljubav, novac i dani kada ti je najlakše da se otvoriš.", "Dom, ljubav i tvoji najbolji dani."],
  Lav: ["Ljubav, posao, novac i dani kada je scena zaista tvoja.", "Ljubav, posao i dani za tvoju scenu."],
  Devica: ["Posao, zdravlje, ljubav i dani kada detalji rade za tebe.", "Posao, zdravlje i najbolji dani."],
  Vaga: ["Veze, posao, novac i dani kada je lako naći ravnotežu.", "Veze, posao i dani ravnoteže."],
  "Škorpija": ["Ljubav, poverenje, novac i dani kada vredi ići do kraja.", "Ljubav, novac i dani za iskren razgovor."],
  Strelac: ["Ljubav, posao, novac i dani kada vredi krenuti dalje.", "Ljubav, posao i dani za polazak."],
  Jarac: ["Posao, novac, ljubav i dani kada tvoj trud najviše znači.", "Posao, novac i dani za sledeći korak."],
  Vodolija: ["Prijatelji, ljubav, posao i dani kada ideje lako prolaze.", "Prijatelji, ljubav i dani za ideje."],
  Ribe: ["Ljubav, odmor, novac i dani kada možeš da veruješ osećaju.", "Ljubav, odmor i dani samo za tebe."],
};
const long = (s: string) => TAIL[s]?.[0] ?? "Ljubav, posao, novac i najbolji dani.";
const short = (s: string) => TAIL[s]?.[1] ?? "Ljubav, posao i najbolji dani.";

